  if (!/^(?:(?:[A-Za-z0-9]+_)?[0-9a-fA-F]{8}-?[0-9a-fA-F]{4}-?[0-9a-fA-F]{4}-?[0-9a-fA-F]{4}-?[0-9a-fA-F]{12}|[A-Za-z0-9][A-Za-z0-9_-]{0,63})$/.test(id)) {
    return problemJson(c, ValidationErrors.invalidId("id", "a UUID (or a prefixed id minted before generateId defaulted to uuid), or a hand-written id (letters, digits, _ and -)"), 400);
  }

  let effectiveCtx = ctx;

  

